INSERT INTO `lkt_payment` (`id`, `name`, `type`, `class_name`, `description`, `logo`, `status`, `sort`, `note`, `poundage`, `poundage_type`, `client_type`) VALUES (1, '支付宝手机支付', 1, 'alipay', '支付宝的手机网站支付方式。需要企业账号单独签约设置密钥。不能与电脑版本的支付宝混用。<a href=\"http://www.alipay.com/\" target=\"_blank\">立即申请</a>', 'https://laikeds.oss-cn-shenzhen.aliyuncs.com/1/0/1547705358393.png', 1, 99, '', 0.00, 1, 2);
INSERT INTO `lkt_payment` (`id`, `name`, `type`, `class_name`, `description`, `logo`, `status`, `sort`, `note`, `poundage`, `poundage_type`, `client_type`) VALUES (2, '中国银联手机支付', 1, 'wap_unionpay', '中国银联unionpay手机网站支付接口。费率相对较低，而且支持银行数量最广泛，注意：商户的 <签名证书>和<密码加密证书>都必须放置到商城根目录下的 \"/plugins/payments/pay_wap_unionpay/key\" 目录中。<a href=\"https://open.unionpay.com/ajweb/index\" target=\"_blank\">立即申请</a>', 'https://laikeds.oss-cn-shenzhen.aliyuncs.com/1/0/1547705291753.png', 1, 99, '', 0.00, 1, 2);
INSERT INTO `lkt_payment` (`id`, `name`, `type`, `class_name`, `description`, `logo`, `status`, `sort`, `note`, `poundage`, `poundage_type`, `client_type`) VALUES (3, '钱包', 2, 'wallet_pay', '货到付款', '', 1, 99, '', 0.00, 1, 3);
