INSERT INTO `lkt_product_list` (`id`, `store_id`, `product_number`, `commodity_type`, `product_title`, `subtitle`, `label`, `scan`, `product_class`, `imgurl`, `content`, `richList`, `sort`, `add_date`, `upper_shelf_time`, `volume`, `initial`, `s_type`, `num`, `min_inventory`, `status`, `brand_id`, `is_distribution`, `is_default_ratio`, `keyword`, `weight`, `weight_unit`, `distributor_id`, `freight`, `is_zhekou`, `separate_distribution`, `recycle`, `gongyingshang`, `is_hexiao`, `hxaddress`, `active`, `mch_id`, `mch_status`, `refuse_reasons`, `search_num`, `show_adr`, `publisher`, `is_zixuan`, `commodity_str`, `source`, `comment_num`, `cover_map`, `class_sort`, `display_position_sort`) VALUES (1022, 1, 'L18-K001-T826', 0, '现货Apple苹果iPhone11', '现货Apple苹果iPhone11Pro苹果11国行港版美版新款双卡手机', '', '', '-464-465-', 'a6022232401133.jpg', '<p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;text-align: center;\"><span style=\"font-family:microsoft yahei\"><span style=\"font-size: 18.0px;\">國行三網通11Pro 256G暗夜綠優惠價8128現貨秒發！</span></span></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i1/20543624/O1CN01LjhVmJ1cdpuSldtuJ_!!20543624.jpg\" style=\"max-width: 750.0px;\"/></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><span style=\"background-color: #ffffff;color: #000000;font-style: normal;font-weight: normal;letter-spacing: normal;margin: 1.12em 0.0px;orphans: 2;padding: 0.0px;text-align: start;text-indent: 0.0px;text-transform: none;widows: 2;word-spacing: 0.0px;\"><span style=\"font-size: 24.0px;\">港版和國行是全網通支持雙卡雙待,美版是無鎖全網通不支持雙卡雙待</span></span></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-size: 14.0px;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><span style=\"font-size: 24.0px;\">官方標配國行/港版/美版都是全新未激活,全套原裝配件現貨當天發！</span></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-size: 14.0px;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><span style=\"font-size: 24.0px;\">支持深圳同城閃送，2小時送達運費自理。</span></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-size: 14.0px;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i4/20543624/O1CN01XqVkbm1cdpu1SfOkp_!!20543624.jpg\" style=\"max-width: 750.0px;\"/><span style=\"font-size: 24.0px;\">歡迎光臨十五年淘寶老店超盈國際HK，</span><span style=\"font-size: 24.0px;\">本店專注蘋果新品發售已有十載，很多客戶從iPhone4開始就關注本店。可先收藏加購本寶貝，時刻關注新款iPhone11& iPhone11 Pro&iPhone 11 Pro Max到貨情況及優惠價。</span></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-size: 14.0px;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i1/20543624/O1CN01jOgbbi1cdptw1I1jV_!!20543624.jpg\" style=\"max-width: 750.0px;\"/><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i3/20543624/O1CN01KF9FXG1cdpu0h7vX8_!!20543624.jpg\" style=\"max-width: 750.0px;\"/></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-size: 14.0px;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><span style=\"color: #ff0000;\"><span style=\"background-color: #ffffff;font-style: normal;font-weight: normal;letter-spacing: normal;margin: 1.12em 0.0px;orphans: 2;padding: 0.0px;text-align: start;text-indent: 0.0px;text-transform: none;widows: 2;word-spacing: 0.0px;\"><span style=\"font-size: 24.0px;\">官方標配：全新原封未激活,原裝充電器數據線耳機零售機；</span></span></span></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-size: 14.0px;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><span style=\"color: #ff0000;\"><span style=\"background-color: #ffffff;font-style: normal;font-weight: normal;letter-spacing: normal;margin: 1.12em 0.0px;orphans: 2;padding: 0.0px;text-align: start;text-indent: 0.0px;text-transform: none;widows: 2;word-spacing: 0.0px;\"><span style=\"font-size: 24.0px;\">套餐六美版；全新無鎖三網通近期激活，原裝充電器數據線耳機；</span></span></span></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;color: #000000;font-size: 14.0px;font-style: normal;font-weight: normal;letter-spacing: normal;orphans: 2;text-align: start;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i4/20543624/O1CN015yjRPO1cdpu2RvT3a_!!20543624.jpg\" style=\"max-width: 750.0px;\"/><img align=\"absmiddle\" src=\"https://i