INSERT INTO `lkt_product_list` (`id`, `store_id`, `product_number`, `commodity_type`, `product_title`, `subtitle`, `label`, `scan`, `product_class`, `imgurl`, `content`, `richList`, `sort`, `add_date`, `upper_shelf_time`, `volume`, `initial`, `s_type`, `num`, `min_inventory`, `status`, `brand_id`, `is_distribution`, `is_default_ratio`, `keyword`, `weight`, `weight_unit`, `distributor_id`, `freight`, `is_zhekou`, `separate_distribution`, `recycle`, `gongyingshang`, `is_hexiao`, `hxaddress`, `active`, `mch_id`, `mch_status`, `refuse_reasons`, `search_num`, `show_adr`, `publisher`, `is_zixuan`, `commodity_str`, `source`, `comment_num`, `cover_map`, `class_sort`, `display_position_sort`) VALUES (1048, 1, 'L18-K001-T855', 0, '外贸牛津单鞋粗跟英伦风大码女鞋37404142码', '外贸牛津单鞋粗跟英伦风大码女鞋37404142码', '', '', '-464-465-', 'a5272807680310.jpg', '<p style=\"color: #000000;text-align: center;\"><span style=\"color: #ff0000;font-family: tahoma   arial   宋體   sans-serif;font-size: 36.0px;font-style: normal;font-weight: 400;letter-spacing: normal;orphans: 2;text-align: center;text-indent: 0.0px;text-transform: none;widows: 2;word-spacing: 0.0px;background-color: #ffffff;display: inline;float: none;\">店主外省定居，</span><img alt=\"\" src=\"https://assets.alicdn.com/sys/wangwang/smiley/48x48/46.gif\" style=\"border: 0.0px;vertical-align: top;color: #ff0000;font-family: tahoma   arial   宋體   sans-serif;font-size: 36.0px;font-style: normal;font-weight: 400;letter-spacing: normal;orphans: 2;text-align: center;text-indent: 0.0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0.0px;background-color: #ffffff;width: 48.0px;height: 48.0px;\"/><span style=\"color: #ff0000;font-family: tahoma   arial   宋體   sans-serif;font-size: 36.0px;font-style: normal;font-weight: 400;letter-spacing: normal;orphans: 2;text-align: center;text-indent: 0.0px;text-transform: none;widows: 2;word-spacing: 0.0px;background-color: #ffffff;display: inline;float: none;\">無底線賠錢處理所有鞋子，不退貨了，有合適的不要錯過啦。</span></p><p style=\"color: #000000;text-align: center;\">&nbsp;</p><p style=\"color: #000000;text-align: center;\">&nbsp;</p><p style=\"color: #000000;text-align: center;\">&nbsp;</p><p style=\"color: #000000;text-align: center;\">&nbsp;</p><p style=\"color: #000000;text-align: center;\">&nbsp;</p><p style=\"color: #000000;text-align: center;\"><span style=\"color: #274e13;\">平時最好搭配，穿着又舒適，不累腳的鞋子。</span><span style=\"color: #274e13;line-height: 1.5;\">&nbsp;</span></p><p style=\"color: #000000;text-align: center;\"><span style=\"color: #274e13;\">這款鞋子採用了個性金屬裝飾 大品牌設計</span></p><p style=\"color: #000000;text-align: center;\"><span style=\"color: #274e13;\">藍色是鄂魚紋大氣材料 &nbsp;<span style=\"line-height: 1.5;\">黑色是亮面PU軟麵的 &nbsp;</span><span style=\"line-height: 1.5;\">內裡是透氣的布裏</span></span></p><p style=\"text-align: center;\"><span style=\"color: #274e13;\"><span style=\"line-height: 1.5;\">&nbsp;</span><span style=\"line-height: 1.5;\">鞋墊是</span><span style=\"line-height: 1.5;\">豬p內裡 &nbsp;&nbsp;</span><span style=\"line-height: 1.5;\">非常不錯哦</span></span></p><p style=\"color: #000000;text-align: left;\">鞋跟高：約3.5Cm</p><p style=\"color: #000000;text-align: left;\">&nbsp;</p><p style=\"color: #000000;text-align: left;\">鞋底：橡皮大底耐磨防滑</p><p style=\"color: #000000;text-align: left;\">&nbsp;</p><p style=\"color: #000000;text-align: left;\">尺碼：37-41（正常外貿碼），38開始偏大點，39開始偏大多一點；大腳胖的，喜歡寬鬆的也可以考慮正常選碼；碼數只是給親們個建議，不作爲標準，怕不合適的可以購買運費險。（有買家說我們推薦的碼數不合適，退貨要我拿郵費，對不起哈，誰也不可能保證鞋子就適合每一位 買家，我們是人不是神，別要求那麼高，我們盡力了）</p><p style=\"color: #000000;text-align: left;\">&nbsp;</p><p style=\"color: #000000;text-align: left;\">試穿：店主腳長27cm（平時穿男款帆布鞋42-43碼），穿絲襪試穿這款41碼合適<span style=\"text-align: center;line-height: 1.5;\">&nbsp;</span></p><p style=\"color: #000000;text-align: left;\">&nbsp;</p><p style=\"color: #000000;\"><span style=\"font-size: 14.0px;\"><strong style=\"line-height: 1.5;text-align: center;\"><span style=\"line-height: 27.0px;font-family: impact;\">注：外貿庫存商品難免會有不影響穿着的小瑕辭（裝飾物不對稱，車線不穩，小劃痕，膠水印，皮子褶皺不均勻，碰髒，線頭，做工不精良），所以要求很高的MM請考慮哦。完美主義者請繞行 移駕去專櫃挑選完美的東東</span></strong></span></p><p style=\"color: #000000;\"><span style=\"font-size: 14.0px;\"><span style=\"color: #000000;\"><strong><strong><strong style=\"color: #0000ff;\"><span style=\"background-color: #ffff00;\"><span style=\"background-color: #ff0000;\"><span style=\"background-color: #fff2cc;\">（這款的金屬裝飾加薄膜保護且是用鑽固定的，不用擔心會掉下來，左右腳的金屬裝飾可能會有點偏差這樣）介意請慎拍！</span></span></span></strong></strong></strong></span></span></p><p style=\"color: #000000;text-align: center;\">&nbsp;</p><p style=\"color: #000000;text-align: center;\">&nbsp;</p><p style=\"color: #000000;\">&nbsp;</p><p style=\"color: #000000;text-align: center;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i2/65431084/TB25ojSkpXXXXX1XpXXXXXXXXXX_!!65431084.jpg\"/><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i3/65431084/TB25RrwkpXXXXXNXXXXXXXXXXXX_!!65431084.jpg\"/><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i2/65431084/TB28QHkkpXXXXb8XXXXXXXXXXXX_!!65431084.jpg\"/><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i4/65431084/TB2ehvbkpXXXXXeXpXXXXXXXXXX_!!65431084.jpg\"/><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i1/65431084/TB2m6fkkpXXXXb1XXXXXXXXXXXX_!!65431084.jpg\"/></p><p style=\"color: rgb(0, 0, 0); text-align: center;\">&nbsp;</p>', '', 1661, '2020-11-30 13:50:34', '2020-11-30 13:50:33', 0, 'a:5:{s:3:\"cbj\";s:2:\"16\";s:2:\"yj\";s:2:\"16\";s:2:\"sj\";s:2:\"16\";s:4:\"unit\";s:3:\"件\";s:5:\"kucun\";s:3:\"100\";}', ',1,', 984, 10, 1, 153, 0, 0, '外贸牛津单鞋粗跟英伦风大码女鞋37-404142码  独钓寒江ll 辽宁鞍山', '0.00', NULL, 0, '127', 0, '0', 1, '', 0, '', '1', 184, 2, NULL, 0, ',0,', '店铺1', 0, NULL, 2, 0, 'a5272807680310.jpg', 0, 0);
