INSERT INTO `lkt_product_list` (`id`, `store_id`, `product_number`, `commodity_type`, `product_title`, `subtitle`, `label`, `scan`, `product_class`, `imgurl`, `content`, `richList`, `sort`, `add_date`, `upper_shelf_time`, `volume`, `initial`, `s_type`, `num`, `min_inventory`, `status`, `brand_id`, `is_distribution`, `is_default_ratio`, `keyword`, `weight`, `weight_unit`, `distributor_id`, `freight`, `is_zhekou`, `separate_distribution`, `recycle`, `gongyingshang`, `is_hexiao`, `hxaddress`, `active`, `mch_id`, `mch_status`, `refuse_reasons`, `search_num`, `show_adr`, `publisher`, `is_zixuan`, `commodity_str`, `source`, `comment_num`, `cover_map`, `class_sort`, `display_position_sort`) VALUES (1054, 1, 'L18-K001-T864', 0, '国标成人电动山地车', '国标成人电动山地车减震变速助力自行车可拆卸锂电池越野长跑48V', '', '', '-464-465-', 'a5909885479830.jpg', '<p style=\"margin: 1.12em 0.0px;padding: 0.0px;font-size: 14.0px;background-color: #ffffff;\"><span style=\"font-size: 24.0px;\">&nbsp; &nbsp; &nbsp; 本公司專業生產電動腳踏車十多年，這是我公司最新研發的隱藏式可拆卸充電的電動腳踏車，有專業的設計研發團隊.高性能運動自行車及電動腳踏車各類產品,款式新穎，風格多變，質優價美，產品銷歐美，南美等多個國家。國內中高端市場.歡迎廣大消費者前來購買,或批發零售，同時歡迎</span><span style=\"font-size: 24.0px;\">進出口公司親臨本公司洽談合作！&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span></p><p style=\"margin: 1.12em 0.0px;padding: 0.0px;font-size: 14.0px;background-color: #ffffff;\"><span style=\"font-size: 24.0px;\">現面向全國各大城市誠招區域代理商.</span></p><p><span style=\"color: white;line-height: 0.0px;font-size: 0.0px;\">- -_- -</span></p><p><span style=\"color: white;line-height: 0.0px;font-size: 0.0px;\">- -_- -</span><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i1/2909581369/O1CN01DbX3El1Lz2md0wpXT_!!2909581369.jpg\" style=\"max-width: 750.0px;\"/><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i1/2909581369/O1CN01BzXIC01Lz2md0vpBv_!!2909581369.jpg\" style=\"max-width: 750.0px;\"/><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i4/2909581369/O1CN01GiHOOA1Lz2mhz