INSERT INTO `lkt_product_list` (`id`, `store_id`, `product_number`, `commodity_type`, `product_title`, `subtitle`, `label`, `scan`, `product_class`, `imgurl`, `content`, `richList`, `sort`, `add_date`, `upper_shelf_time`, `volume`, `initial`, `s_type`, `num`, `min_inventory`, `status`, `brand_id`, `is_distribution`, `is_default_ratio`, `keyword`, `weight`, `weight_unit`, `distributor_id`, `freight`, `is_zhekou`, `separate_distribution`, `recycle`, `gongyingshang`, `is_hexiao`, `hxaddress`, `active`, `mch_id`, `mch_status`, `refuse_reasons`, `search_num`, `show_adr`, `publisher`, `is_zixuan`, `commodity_str`, `source`, `comment_num`, `cover_map`, `class_sort`, `display_position_sort`) VALUES (1378, 1, '35730168134', 0, '包邮进口技术夹缝架冰箱间隙缝隙收纳整理架厨房浴室置物架', '包邮进口技术夹缝架冰箱间隙缝隙收纳整理架厨房浴室置物架', '', '35730168134', '-484-528-', 'a357301681340.jpg', '\n    \n    \n    \n    \n    <p style=\"text-align: center;\"><span style=\"font-size: 36.0px;\"><span style=\"color: #ff0000;\"><span style=\"font-family: kaiti_gb2312;\"><strong><strong><font color=\"#ff0000\" face=\"楷體_GB2312\" size=\"7\"><img align=\"absMiddle\" src=\"https://img.alicdn.com/imgextra/i3/674046106/T2QXc6XeRXXXXXXXXX_!!674046106.jpg_q50s50.jpg_.webp\">包郵進行中！ &nbsp; &nbsp;&nbsp;</font></strong></strong></span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"font-size: 24.0px;color: #ff0000;font-family: simhei;line-height: 1.5;\">&nbsp;加厚款縫隙收納層架！大瓶洗衣液什麼隨便你放幾瓶 ，如果覺得不滿意可以免費退貨我們都爲您買了運費險的所以大家可以放心購買！</span></p>\n\n<p><span style=\"font-size: 36.0px;\"><span style=\"color: #ff0000;\"><span style=\"font-family: kaiti_gb2312;\"><strong><strong><span style=\"font-size: 24.0px;\">一：江蘇，浙江，上海，安徽，</span><span style=\"font-size: 24.0px;\">山東，福建，江西，湖南，湖北，河南，河北，天津，北京包郵；</span></strong></strong></span></span></span></p>\n\n<p><span style=\"font-size: 36.0px;\"><span style=\"color: #ff0000;\"><span style=\"font-family: kaiti_gb2312;\"><strong><strong><span style=\"font-size: 24.0px;\">二：雲南，貴州，四川，重慶，黑龍江，遼寧，吉林，山西，陜西，廣西，海南包郵；</span></strong></strong></span></span></span></p>\n\n<p><span style=\"font-size: 36.0px;\"><span style=\"color: #ff0000;\"><span style=\"font-family: kaiti_gb2312;\"><strong><strong><span style=\"font-size: 24.0px;\">三：新疆，西藏，青海，甘肅，內蒙古，寧夏，港澳臺不包郵，按實際運費收取 藍色變深藍了介意的朋友慎拍</span></strong></strong></span></span></span></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size: 36.0px;\"><span style=\"color: #ff0000;\"><span style=\"font-family: kaiti_gb2312;\"><strong><span style=\"font-size: 24.0px;\">【規格】長寬高尺寸排列二層（54*12*41）三層（54*12*72cm）、</span></strong></span></span></span><strong style=\"color: #ff0000;font-family: kaiti_gb2312;font-size: 36.0px;line-height: 54.0px;\"><span style=\"font-size: 24.0px;\"><strong>四層（54*12*103cm）</strong></span></strong></p>\n\n<p><span style=\"font-size: 36.0px;\"><span style=\"color: #ff0000;\"><span style=\"font-family: kaiti_gb2312;\"><strong><span style=\"font-size: 24.0px;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></strong></span></span></span></p>\n\n<p><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i1/674046106/O1CN01dyLuX81uyb3cq1LXP_!!674046106.jpg_q50s50.jpg_.webp\" style=\"max-width: 750.0px;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i4/674046106/O1CN01dWk2qx1uyb3QEU84N_!!674046106.jpg_q50s50.jpg_.webp\" style=\"max-width: 750.0px;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i2/674046106/O1CN01rrp7T41uyb3fzWk3A_!!674046106.jpg_q50s50.jpg_.webp\" style=\"max-width: 750.0px;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i3/674046106/O1CN01zarizB1uyb3UwQhNQ_!!674046106.jpg_q50s50.jpg_.webp\" style=\"max-width: 750.0px;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i2/674046106/O1CN01ftSwvF1uyb3ZNXTxN_!!674046106.jpg_q50s50.jpg_.webp\" style=\"max-width: 750.0px;\"><img align=\"absmiddle\" src=\"https://img.alicdn.com/imgextra/i3/674046106/O1CN01hBc9rN1uyb3QEUStJ_!!674046106.jpg_q50s50.jpg_.webp\" style=