-- ----------------------------
-- Table structure for lkt_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_config`;
CREATE TABLE `lkt_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `is_register` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否需要注册 1.注册 2.免注册',
  `logo` varchar(100) DEFAULT NULL COMMENT '公司logo',
  `logo1` varchar(100) DEFAULT NULL COMMENT '首页logo',
  `company` varchar(100) NOT NULL DEFAULT '' COMMENT '公司名称',
  `appid` char(18) NOT NULL DEFAULT '' COMMENT '小程序id',
  `appsecret` char(32) NOT NULL DEFAULT '' COMMENT '小程序密钥',
  `domain` varchar(100) NOT NULL DEFAULT '' COMMENT '商城根目录域名',
  `app_domain_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'APP域名',
  `H5_domain` varchar(255) DEFAULT NULL COMMENT 'H5域名',
  `mch_id` int(11) DEFAULT NULL COMMENT '商户id',
  `ip` varchar(25) DEFAULT NULL COMMENT 'ip地址',
  `uploadImg_domain` varchar(100) NOT NULL DEFAULT '' COMMENT '图片上传域名',
  `upserver` tinyint(4) NOT NULL DEFAULT '2' COMMENT '上传服务器:1,本地　2,阿里云 3,腾讯云 4,七牛云',
  `uploadImg` varchar(100) NOT NULL DEFAULT '' COMMENT '图片上传位置',
  `upload_file` varchar(100) NOT NULL DEFAULT '' COMMENT '文件上传位置',
  `modify_date` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `mch_key` varchar(100) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '微信支付key',
  `mch_cert` varchar(100) NOT NULL DEFAULT '' COMMENT '支付证书文件地址',
  `user_id` varchar(20) DEFAULT '' COMMENT '用户ID默认前缀',
  `wx_name` varchar(255) DEFAULT NULL COMMENT '微信默认用户名称',
  `wx_headimgurl` varchar(255) DEFAULT NULL COMMENT '微信默认用户头像',
  `customer_service` text COMMENT '客服',
  `agreement` text COMMENT '用户协议',
  `aboutus` text COMMENT '关于我们',
  `message_day` int(10) NOT NULL DEFAULT '0' COMMENT '消息保留天数',
  `tencent_key` varchar(255) DEFAULT NULL COMMENT '腾讯位置服务开发密钥',
  `after_sales_issues` text COMMENT '售后问题',
  `payment_issues` text COMMENT '支付问题',
  `shopping_process` text COMMENT '购物流程',
  `payment_method` text COMMENT '付款方式',
  `return_policy` text COMMENT '退货政策',
  `cancellation_order` text COMMENT '取消订单',
  `refund_process` text COMMENT '退款流程',
  `refund_instructions` text COMMENT '退款说明',
  `exp_time` int(11) DEFAULT '2' COMMENT '移动端登录有效期',
  `is_push` tinyint(4) DEFAULT '0' COMMENT '是否推送 0.不推送 1.推送',
  `push_Appkey` varchar(255) DEFAULT NULL COMMENT '推送Appkey',
  `push_Appid` varchar(255) DEFAULT NULL COMMENT '推送Appid',
  `push_MasterECRET` varchar(255) DEFAULT NULL COMMENT '推送秘钥',
  `is_express` tinyint(4) DEFAULT '0' COMMENT '是否开启快递100  0.不开启 1.开\r\n\r\n启',
  `express_address` varchar(255) DEFAULT NULL COMMENT '查询接口地址',
  `express_number` varchar(255) DEFAULT NULL COMMENT '用户编号',
  `express_key` varchar(255) DEFAULT NULL COMMENT '接口调用key',
  `is_Kicking` tinyint(4) DEFAULT '0' COMMENT '是否登录踢人  0.不开启 1.开启',
  `Hide_your_wallet` tinyint(4) DEFAULT '0' COMMENT '是否隐藏钱包 0.不隐藏 1.隐藏',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=146 DEFAULT CHARSET=utf8 COMMENT='配置表';

-- ----------------------------
-- Records of lkt_config
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_configure
-- ----------------------------
DROP TABLE IF EXISTS `lkt_configure`;
CREATE TABLE `lkt_configure` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '配置id',
  `name` varchar(100) DEFAULT NULL COMMENT '配置名称',
  `color` char(15) NOT NULL COMMENT '颜色',
  `size` varchar(100) NOT NULL DEFAULT '0' COMMENT '尺码',
  `costprice` decimal(12,2) NOT NULL COMMENT '成本价',
  `price` decimal(12,2) NOT NULL COMMENT '出售价格',
  `yprice` decimal(12,2) NOT NULL COMMENT '原价格',
  `img` varchar(255) NOT NULL COMMENT '图片',
  `pid` int(11) NOT NULL COMMENT '商品id',
  `total_num` int(11) NOT NULL DEFAULT '0' COMMENT '总库存',
  `num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '剩余库存',
  `unit` varchar(30) NOT NULL COMMENT '单位',
  `bar_code` varchar(255) NOT NULL COMMENT '条形码',
  `bargain_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '砍价开始价格',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 0:未开启砍价 1:开启砍价 2 上架 3 缺货 4下架',
  `attribute` text COMMENT '属性',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `min_inventory` smallint(6) NOT NULL DEFAULT '10' COMMENT '产品预警值',
  `ctime` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `attribute_str` text COMMENT '属性ID字符串',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `pid` (`pid`)
) ENGINE=InnoDB AUTO_INCREMENT=17513 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='商品配置表';

-- ----------------------------
-- Records of lkt_configure
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_core_menu
-- ----------------------------
DROP TABLE IF EXISTS `lkt_core_menu`;
CREATE TABLE `lkt_core_menu` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `s_id` int(11) DEFAULT NULL COMMENT '上级id',
  `title` varchar(60) NOT NULL DEFAULT '' COMMENT '菜单名称',
  `name` varchar(60) NOT NULL DEFAULT '' COMMENT '菜单标识',
  `image` varchar(255) DEFAULT NULL COMMENT '图标',
  `image1` varchar(255) DEFAULT NULL COMMENT '点击后图标',
  `module` varchar(60) NOT NULL DEFAULT '' COMMENT '菜单模块标识',
  `action` varchar(60) NOT NULL DEFAULT '' COMMENT '菜单文件标识',
  `url` varchar(60) NOT NULL DEFAULT '' COMMENT '路径',
  `sort` int(11) DEFAULT '0' COMMENT '菜单排序',
  `level` int(11) DEFAULT NULL COMMENT '第几级',
  `is_button` int(4) NOT NULL DEFAULT '0' COMMENT '是否为按钮',
  `is_core` tinyint(4) DEFAULT '0' COMMENT '是否是核心',
  `is_plug_in` tinyint(4) DEFAULT '0' COMMENT '是否是插件',
  `type` tinyint(4) DEFAULT '0' COMMENT '类型 0=控制台 1=商城',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `is_display` tinyint(4) DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `briefintroduction` text COMMENT '简介',
  `guide_sort` int(11) DEFAULT '0' COMMENT '导览排序',
  `guide_name` varchar(255) DEFAULT NULL COMMENT '导览名称',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=781 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='核心菜单';

-- ----------------------------
-- Records of lkt_core_menu
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_coupon
-- ----------------------------
DROP TABLE IF EXISTS `lkt_coupon`;
CREATE TABLE `lkt_coupon` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `user_id` varchar(15) NOT NULL COMMENT '用户ID',
  `money` int(11) NOT NULL DEFAULT '0' COMMENT '优惠券金额',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '领取时间',
  `expiry_time` timestamp NULL DEFAULT NULL COMMENT '到期时间',
  `hid` int(11) NOT NULL DEFAULT '0' COMMENT '活动id',
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0:未使用 1:使用中 2:已使\r\n\r\n用 3:已过期',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态 0.开启 1.禁用',
  `free_or_not` tinyint(3) DEFAULT '0' COMMENT '是否为赠送 0.不为赠送 1.赠送',
  `recycle` tinyint(4) DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=830 DEFAULT CHARSET=utf8 COMMENT='优惠券表';

-- ----------------------------
-- Records of lkt_coupon
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_coupon_activity
-- ----------------------------
DROP TABLE IF EXISTS `lkt_coupon_activity`;
CREATE TABLE `lkt_coupon_activity` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺id',
  `name` varchar(25) NOT NULL COMMENT '优惠券名称',
  `activity_type` int(11) DEFAULT '0' COMMENT '优惠券类型 1=免邮 2=满减 3=折扣 4=会员赠送',
  `grade_id` int(11) DEFAULT NULL COMMENT '会员等级ID',
  `money` decimal(12,2) DEFAULT '0.00' COMMENT '优惠券面值',
  `discount` decimal(12,2) DEFAULT '0.00' COMMENT '折扣值',
  `z_money` decimal(12,2) DEFAULT '0.00' COMMENT '消费满多少',
  `shopping` int(11) NOT NULL DEFAULT '0' COMMENT '满多少赠券',
  `free_mail_task` tinyint(4) NOT NULL DEFAULT '0' COMMENT '免邮任务 0：完善资料 1：绑定手机',
  `circulation` int(11) DEFAULT NULL COMMENT '发行数量',
  `num` int(11) DEFAULT NULL COMMENT '剩余数量',
  `receive` int(11) DEFAULT NULL COMMENT '领取限制',
  `use_num` int(11) DEFAULT NULL COMMENT '使用限制',
  `start_time` timestamp NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '结束时间',
  `type` tinyint(4) DEFAULT '1' COMMENT '优惠券使用范围 1：全部商品 2:指定商品 3：指定分类',
  `product_class_id` text COMMENT '活动指定商品类型id',
  `product_id` text COMMENT '活动指定商品id',
  `content` text COMMENT '备注',
  `skip_type` tinyint(4) DEFAULT '1' COMMENT '跳转方式 1.首页 2.\r\n\r\n自定义',
  `url` varchar(255) DEFAULT NULL COMMENT '跳转路径',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态 0：未启用 1：启用 2:禁用 3：已结束',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `qualifications` text COMMENT '资格',
  `recycle` tinyint(4) DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `day` int(11) DEFAULT NULL COMMENT '有效时间',
  `Instructions` text COMMENT '使用说明',
  `is_display` tinyint(4) DEFAULT '1' COMMENT '是否显示 0.不显示 1.显示',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=310 DEFAULT CHARSET=utf8 COMMENT='优惠劵活动表';

-- ----------------------------
-- Records of lkt_coupon_activity
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
