-- ----------------------------
-- Table structure for lkt_mch
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch`;
CREATE TABLE `lkt_mch` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) DEFAULT NULL COMMENT '用户id',
  `name` varchar(255) DEFAULT NULL COMMENT '店铺名称',
  `shop_information` text COMMENT '店铺信息',
  `shop_range` text COMMENT '经营范围',
  `realname` varchar(255) DEFAULT NULL COMMENT '真实姓名',
  `ID_number` varchar(255) DEFAULT NULL COMMENT '身份证号码',
  `tel` varchar(255) DEFAULT NULL COMMENT '联系电话',
  `sheng` char(100) DEFAULT NULL,
  `shi` char(100) DEFAULT NULL,
  `xian` char(100) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL COMMENT '联系地址',
  `logo` varchar(255) DEFAULT NULL COMMENT '店铺Logo',
  `shop_nature` tinyint(3) NOT NULL DEFAULT '0' COMMENT '店铺性质：0.个人 1.企业',
  `business_license` varchar(255) DEFAULT NULL COMMENT '营业执照',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '申请时间',
  `review_time` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `review_status` tinyint(3) NOT NULL DEFAULT '0' COMMENT '审核状态：0.待审核 1.审核通过 2.审核不通过',
  `review_result` varchar(255) DEFAULT NULL COMMENT '拒绝理由',
  `integral_money` decimal(12,0) DEFAULT '0' COMMENT '商户积分',
  `account_money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '商户余额',
  `collection_num` int(11) DEFAULT '0' COMMENT '收藏数量',
  `is_open` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否营业：0.未营业 1.营业中 2.打烊',
  `is_lock` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否被系统关闭：0.否 1.是',
  `confines` varchar(255) DEFAULT NULL COMMENT '店铺经营范围',
  `mch_service` text COMMENT '店铺客服',
  `business_hours` varchar(255) DEFAULT NULL COMMENT '营业时间',
  `roomid` int(11) unsigned DEFAULT '0',
  `old_roomid` int(11) DEFAULT '0' COMMENT '旧房间ID',
  `longitude` varchar(255) DEFAULT NULL COMMENT '经度',
  `latitude` varchar(255) DEFAULT NULL COMMENT '纬度',
  `cashable_money` decimal(12,2) DEFAULT '0.00' COMMENT '可取现金额',
  `recovery` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否回收 0.未回收 1.回收',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=254 DEFAULT CHARSET=utf8 COMMENT='商户';

-- ----------------------------
-- Records of lkt_mch
-- ----------------------------
BEGIN;
COMMIT;

