CREATE TABLE `lkt_mch_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `logo` varchar(255) DEFAULT NULL COMMENT '店铺默认logo',
  `settlement` varchar(50) NOT NULL DEFAULT '0' COMMENT '结算方式',
  `min_charge` decimal(12,2) DEFAULT '0.00' COMMENT '最低提现金额\r\n\r\n',
  `max_charge` decimal(12,2) DEFAULT '0.00' COMMENT '最大提现金额\r\n\r\n',
  `service_charge` decimal(12,2) DEFAULT '0.00' COMMENT '手续费',
  `illustrate` text COMMENT '提现说明',
  `agreement` text CHARACTER SET utf8mb4 COMMENT '入驻协议',
  `delete_settings` int(11) DEFAULT '0' COMMENT '删除设置',
  `commodity_setup` varchar(255) DEFAULT '' COMMENT '商品设置  1.上传商品 2.\r\n\r\n自选商品',
  `is_display` tinyint(4) DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `promise_switch` int(11) NOT NULL DEFAULT '0' COMMENT '保证金开关',
  `promise_amt` decimal(10,0) NOT NULL COMMENT '保证金金额',
  `promise_text` text COMMENT '保证金说明',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=234 DEFAULT CHARSET=utf8 COMMENT='商户配置表';

-- ----------------------------
-- Records of lkt_mch_config
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_mch_promise
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_promise`;
CREATE TABLE `lkt_mch_promise` (
  `id` varchar(50) NOT NULL COMMENT '主键',
  `orderNo` varchar(20) NOT NULL COMMENT '订单号',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `promise_amt` decimal(10,0) NOT NULL COMMENT '保证金',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '保证金状态 1=已交 2=已退还',
  `pay_type` varchar(20) NOT NULL DEFAULT 'wallet_pay' COMMENT '支付方式',
  `is_return_pay` int(255) NOT NULL DEFAULT '0' COMMENT '是否退还',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='店铺保证金记录表';

-- ----------------------------
-- Records of lkt_mch_promise
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_mch_store
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_store`;
CREATE TABLE `lkt_mch_store` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `name` varchar(255) DEFAULT NULL COMMENT '门店名称',
  `mobile` char(15) NOT NULL COMMENT '联系电话',
  `business_hours` text NOT NULL COMMENT '营业时间',
  `sheng` char(200) DEFAULT NULL COMMENT '省',
  `shi` char(200) DEFAULT NULL COMMENT '市',
  `xian` char(200) DEFAULT NULL COMMENT '县',
  `address` text COMMENT '详细地址',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `longitude` varchar(255) DEFAULT NULL COMMENT '经度',
  `latitude` varchar(255) DEFAULT NULL COMMENT '纬度',
  `is_default` tinyint(4) DEFAULT '0' COMMENT '是否默认 0.不默认 1.默认',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8 COMMENT='店铺门店表';

-- ----------------------------
-- Records of lkt_mch_store
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_mch_template
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_template`;
CREATE TABLE `lkt_mch_template` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(20) NOT NULL DEFAULT '1' COMMENT '商户id',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '示例图',
  `type` tinyint(4) DEFAULT '1' COMMENT '单据类型 1.发货单 2.快递单',
  `name` varchar(100) NOT NULL COMMENT '模版名称',
  `e_name` varchar(100) DEFAULT NULL COMMENT 'tpl文件名称',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `width` int(10) DEFAULT NULL,
  `height` int(10) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8 COMMENT='商户单据模版表';

-- ----------------------------
-- Records of lkt_mch_template
-- ----------------------------
BEGIN;
COMMIT;

