-- Table structure for lkt_message_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_message_config`;
CREATE TABLE `lkt_message_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `accessKeyId` varchar(50) NOT NULL COMMENT 'accessKeyId',
  `accessKeySecret` varchar(50) NOT NULL COMMENT 'accessKeySecret',
  `SignName` varchar(50) NOT NULL COMMENT '短信签名',
  `add_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COMMENT='短信配置';

-- ----------------------------
-- Records of lkt_message_config
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_message_list
-- ----------------------------
DROP TABLE IF EXISTS `lkt_message_list`;
CREATE TABLE `lkt_message_list` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `type` int(2) NOT NULL DEFAULT '0' COMMENT '类型 0:验证码 1:短信通知',
  `type1` int(2) NOT NULL DEFAULT '0' COMMENT '类别 0:通用 1:申请通过 2:申请拒绝 3:订单提现 4:发货提现 5:收货提现',
  `Template_id` int(11) NOT NULL DEFAULT '0' COMMENT '模板id',
  `content` varchar(50) NOT NULL COMMENT 'code',
  `status` int(2) NOT NULL DEFAULT '0' COMMENT '类型 0:商城 1:店铺',
  `admin_id` varchar(50) NOT NULL COMMENT '客户id/店主id',
  `add_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8 COMMENT='短信列表';

-- ----------------------------
-- Records of lkt_message_list
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_message_logging
-- ----------------------------
DROP TABLE IF EXISTS `lkt_message_logging`;
CREATE TABLE `lkt_message_logging` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺id',
  `type` tinyint(3) NOT NULL DEFAULT '1' COMMENT '消息类型 1.订单(待发货) 2.订单(售后) 3.订单(提醒发货) 4.订单(订单关闭) 5.订单(新订单) 6.订单(收货) 7.商品(审核) 8.商品(下架) 9.商品(补货) 10.商品(新商品上架) 11.商品(分类) 12.商品(品牌)',
  `parameter` varchar(255) NOT NULL COMMENT '参数',
  `content` text COMMENT '内容',
  `is_popup` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否弹窗 0.未弹 1.已弹',
  `read_or_not` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否已读 0.未读 1.已读',
  `add_date` datetime DEFAULT '0000-00-00 00:00:00' COMMENT '添加时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='店铺消息记录表';

-- ----------------------------
-- Records of lkt_message_logging
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_money_point
-- ----------------------------
DROP TABLE IF EXISTS `lkt_money_point`;
CREATE TABLE `lkt_money_point` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(15) NOT NULL COMMENT '用户ID',
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '奖金类型',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '应发金额',
  `s_money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '实发金额',
  `fx_money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '手续费一',
  `tax_money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '手续费二',
  `o_money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '手续费三',
  `si_money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '手续费四',
  `w_money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '手续费五',
  `isf` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否延迟发放',
  `f_time` time NOT NULL COMMENT '发放时间',
  `from_ordersn` varchar(15) NOT NULL COMMENT '订单编号',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='奖金收益表';

-- ----------------------------
-- Records of lkt_money_point
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
