-- ----------------------------
DROP TABLE IF EXISTS `lkt_notice`;
CREATE TABLE `lkt_notice` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '配置id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `pay_success` varchar(100) DEFAULT NULL COMMENT '支付成功通知',
  `order_delivery` varchar(100) DEFAULT NULL COMMENT '发货通知',
  `delivery` varchar(100) DEFAULT NULL COMMENT '订单发货通知',
  `refund_res` varchar(100) DEFAULT NULL COMMENT '退款通知',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='模板消息表';

