  `c_name` varchar(50) DEFAULT NULL COMMENT '中文名称',
  `e_name` varchar(255) DEFAULT NULL,
  `stock_id` varchar(50) DEFAULT NULL COMMENT '微信模板库id',
  `stock_key` varchar(255) DEFAULT NULL COMMENT '组合关键词',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8 COMMENT='模板消息配置表';

