-- Table structure for lkt_option
-- ----------------------------
DROP TABLE IF EXISTS `lkt_option`;
CREATE TABLE `lkt_option` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `group` varchar(255) NOT NULL DEFAULT '' COMMENT '类型',
  `name` varchar(255) NOT NULL COMMENT '软件显示类型',
  `value` longtext NOT NULL COMMENT '操作值',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COMMENT='平台控件表';

