-- ----------------------------
-- Table structure for lkt_order
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order`;
CREATE TABLE `lkt_order` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) NOT NULL COMMENT '用户id',
  `name` varchar(50) DEFAULT '' COMMENT '姓名',
  `mobile` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `num` int(11) DEFAULT NULL COMMENT '数量',
  `old_total` decimal(12,2) DEFAULT '0.00' COMMENT '历史总价',
  `z_price` decimal(12,2) DEFAULT '0.00' COMMENT '总价',
  `sNo` varchar(255) DEFAULT NULL COMMENT '订单号',
  `sheng` text COMMENT '省',
  `shi` text COMMENT '市',
  `xian` text COMMENT '县',
  `address` text COMMENT '详细地址',
  `remark` varchar(32) DEFAULT NULL COMMENT '用户备注',
  `pay` char(15) DEFAULT NULL COMMENT '支付方式',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `arrive_time` timestamp NULL DEFAULT NULL COMMENT '到货时间',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态 0:未付款 1:未发货 2:待收货 5:已完成  7:订单关闭',
  `coupon_id` varchar(255) DEFAULT '0' COMMENT '优惠券id',
  `subtraction_id` int(11) DEFAULT NULL COMMENT '满减活动ID',
  `consumer_money` int(11) DEFAULT '0' COMMENT '消费金',
  `coupon_activity_name` varchar(50) DEFAULT '0' COMMENT '满减活动名称',
  `drawid` int(11) DEFAULT '0' COMMENT '活动ID',
  `otype` char(30) DEFAULT '' COMMENT '订单类型',
  `ptcode` char(15) DEFAULT '' COMMENT '拼团编号',
  `pid` char(10) DEFAULT NULL COMMENT '拼团订单类型:kaituan开团 cantuan参团',
  `ptstatus` smallint(6) DEFAULT NULL COMMENT '拼团状态:0,未付款 1,拼团中 2,拼团成功 3,拼团失败',
  `groupman` char(5) DEFAULT NULL COMMENT '拼团人数',
  `refundsNo` char(30) DEFAULT '' COMMENT '拼团退款单号',
  `trade_no` char(20) DEFAULT '' COMMENT '微信支付单号',
  `is_anonymous` int(1) DEFAULT '0' COMMENT '是否匿名(0,否  1.是',
  `logistics_service` int(1) DEFAULT NULL COMMENT '物流服务',
  `overall_evaluation` int(1) DEFAULT NULL COMMENT '总体评价',
  `spz_price` decimal(10,2) DEFAULT '0.00' COMMENT '商品总价',
  `reduce_price` decimal(10,2) DEFAULT '0.00' COMMENT '查询出的满减金额',
  `coupon_price` decimal(10,2) DEFAULT '0.00' COMMENT '查询出的优惠券金额',
  `red_packet` varchar(255) DEFAULT '0' COMMENT '红包金额',
  `allow` int(8) DEFAULT '0' COMMENT '积分',
  `parameter` text COMMENT '参数',
  `source` tinyint(4) NOT NULL DEFAULT '1' COMMENT '来源 1.小程序 2.app 3.支付宝小程序 4.头条小程序 5.百度小程序 6.pc端 7.H5',
  `delivery_status` int(1) DEFAULT '0' COMMENT '提醒发货',
  `readd` int(2) NOT NULL DEFAULT '0' COMMENT '是否已读（0，未读  1 已读）',
  `remind` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '提醒\r\n\r\n发货时间间隔',
  `offset_balance` decimal(10,2) DEFAULT '0.00' COMMENT '抵扣余额',
  `mch_id` varchar(255) DEFAULT '' COMMENT '店铺ID',
  `zhekou` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '分销折扣',
  `grade_rate` decimal(10,2) DEFAULT '0.00' COMMENT '会员等级折扣',
  `grade_score` int(11) DEFAULT NULL COMMENT '会员购物积分',
  `grade_fan` decimal(12,2) DEFAULT NULL COMMENT '会员返现金额',
  `p_sNo` varchar(50) NOT NULL DEFAULT '' COMMENT '父类订单号',
  `bargain_id` int(11) NOT NULL DEFAULT '0' COMMENT '砍价活动id',
  `comm_discount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '分销折扣',
  `real_sno` varchar(255) DEFAULT NULL COMMENT '调起支付所用订单号',
  `orderId` text COMMENT '官方订单号',
  `baiduId` varchar(200) DEFAULT NULL COMMENT '百度用户ID',
  `remarks` varchar(500) NOT NULL DEFAULT '' COMMENT '订单备注',
  `self_lifting` tinyint(4) DEFAULT '0' COMMENT '自提 0.配送 1.自提',
  `extraction_code` varchar(255) DEFAULT NULL COMMENT '提现码',
  `extraction_code_img` varchar(255) DEFAULT NULL COMMENT '提现码二维码',
  `is_put` tinyint(4) DEFAULT '0' COMMENT '是否发放佣金 0.否 1.是',
  `z_freight` decimal(12,2) DEFAULT '0.00' COMMENT '总运费',
  `manual_offer` decimal(12,2) DEFAULT '0.00' COMMENT '代客下单手动优惠金额',
  `preferential_amount` decimal(12,2) DEFAULT '0.00' COMMENT '优惠金额',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  `single_store` tinyint(4) NOT NULL DEFAULT '0' COMMENT '下单门店',
  `pick_up_store` tinyint(4) NOT NULL DEFAULT '0' COMMENT '取货门店',
  `platform_activities_id` int(11) DEFAULT NULL COMMENT '平台活动管理ID',
  `commission_type` tinyint(1) DEFAULT '0' COMMENT '分销订单结算标识0未结算1已结算',
  `settlement_status` tinyint(1) DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2店铺回收',
  `operation_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '下单类型1用户下单2店铺下单3平台下单',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `store_id` (`store_id`),
  KEY `sNo` (`sNo`),
  KEY `subtraction_id` (`subtraction_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3405 DEFAULT CHARSET=utf8 COMMENT='订单列表';

-- ----------------------------
-- Records of lkt_order
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_order_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order_config`;
CREATE TABLE `lkt_order_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `days` int(11) DEFAULT NULL COMMENT '承若天数',
  `content` varchar(30) DEFAULT NULL COMMENT '承若内容',
  `back` int(11) DEFAULT '2' COMMENT '退货时间',
  `order_failure` int(11) DEFAULT NULL COMMENT '订单失效',
  `order_after` int(3) NOT NULL DEFAULT '7' COMMENT '订单售后时间',
  `company` varchar(20) DEFAULT '天' COMMENT '单位',
  `order_overdue` int(11) DEFAULT '2' COMMENT '订单过期删除时间',
  `unit` varchar(50) DEFAULT '天' COMMENT '单位',
  `modify_date` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `auto_the_goods` int(11) DEFAULT '7' COMMENT '自动收货时间',
  `order_ship` int(11) NOT NULL DEFAULT '0' COMMENT '发货时限',
  `remind` int(11) DEFAULT '1' COMMENT '提醒限制',
  `accesscode` char(100) DEFAULT '' COMMENT '顾客编码',
  `checkword` text COMMENT '校验码',
  `custid` char(100) DEFAULT NULL COMMENT '月结卡号',
  `package_settings` tinyint(4) DEFAULT '0' COMMENT '包邮设置 0.未开启 1.开启',
  `same_piece` int(11) DEFAULT '0' COMMENT '同件',
  `same_order` int(11) DEFAULT '0' COMMENT '同单',
  `auto_good_comment_day` smallint(5) NOT NULL DEFAULT '0' COMMENT '自动评价设置几后自动好评',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8 COMMENT='订单设置';

-- ----------------------------
-- Records of lkt_order_config
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_order_data
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order_data`;
CREATE TABLE `lkt_order_data` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `trade_no` char(32) DEFAULT NULL COMMENT '微信订单号',
  `order_type` varchar(20) NOT NULL COMMENT '订单类型',
  `data` text,
  `addtime` datetime NOT NULL COMMENT '创建时间',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '支付状态 0未支付 1已支付',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='订单临时信息表';

-- ----------------------------
-- Records of lkt_order_data
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_order_details
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order_details`;
CREATE TABLE `lkt_order_details` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) DEFAULT NULL COMMENT '用户id',
  `p_id` int(11) DEFAULT NULL COMMENT '产品id',
  `p_name` varchar(200) DEFAULT NULL COMMENT '产品名称',
  `p_price` decimal(12,2) DEFAULT '0.00' COMMENT '产品价格',
  `num` int(11) DEFAULT NULL COMMENT '数量',
  `unit` varchar(50) DEFAULT NULL COMMENT '单位',
  `r_sNo` varchar(255) DEFAULT NULL COMMENT '订单号',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `deliver_time` timestamp NULL DEFAULT NULL COMMENT '发货时间',
  `arrive_time` timestamp NULL DEFAULT NULL COMMENT '到货时间',
  `r_status` tinyint(4) DEFAULT '0' COMMENT '状态 0:未付款 1:未发货 2:待收货 5:已完成  7:订单关闭',
  `content` text COMMENT '退货原因',
  `reason` char(60) DEFAULT NULL COMMENT 'app退款原因',
  `re_type` tinyint(4) DEFAULT '0' COMMENT '退款类型 1:退货退款  2:退款 3:售后',
  `re_apply_money` float(12,2) DEFAULT NULL COMMENT '用户申请退款金额',
  `re_money` float(12,2) DEFAULT NULL COMMENT '退款金额',
  `real_money` decimal(12,2) DEFAULT '0.00' COMMENT '实际退款金额',
  `re_time` datetime DEFAULT NULL COMMENT '申请退款时间',
  `re_photo` text COMMENT '上传凭证',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `r_content` text COMMENT '拒绝原因',
  `r_type` tinyint(4) DEFAULT '100' COMMENT '类型 100:不在退货退款状态0:审核中 1:同意并让用户寄回 2:拒绝(退货退款) 3:用户已快递 4:收到寄回商品,同意并退款 5：拒绝并退回商品 8:拒绝(退款) 9:同意并退款 10:拒绝(售后)11:同意并且寄回商品 12售后结束',
  `express_id` int(255) DEFAULT NULL COMMENT '快递公司id',
  `courier_num` varchar(40) DEFAULT NULL COMMENT '快递单号',
  `express_type` tinyint(4) DEFAULT '1' COMMENT '发货类型 1.手动发货 2.自动发货',
  `freight` decimal(12,2) DEFAULT '0.00' COMMENT '运费',
  `size` varchar(100) DEFAULT NULL COMMENT '配置名称',
  `sid` char(11) DEFAULT NULL COMMENT '规格属性id',
  `invoice` tinyint(4) DEFAULT '0' COMMENT '发货单打印 0.否 1.是',
  `express` tinyint(4) DEFAULT '0' COMMENT '快递单打印 0.否 1.是',
  `exchange_num` int(11) DEFAULT '0' COMMENT '换货次数',
  `coupon_id` varchar(255) DEFAULT '0' COMMENT '优惠券id',
  `manual_offer` decimal(12,2) DEFAULT '0.00' COMMENT '代课下单手动优惠金额',
  `after_discount` decimal(12,2) DEFAULT '0.00' COMMENT '优惠后的金额',
  `mch_id` int(11) DEFAULT NULL COMMENT '店铺ID',
  `settlement_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '订单结算标识 0未结算 1已结算',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.回收',
  PRIMARY KEY (`id`),
  KEY `store_id` (`store_id`),
  KEY `user_id` (`user_id`),
  KEY `r_sNo` (`r_sNo`),
  KEY `sid` (`sid`)
) ENGINE=InnoDB AUTO_INCREMENT=3472 DEFAULT CHARSET=utf8 COMMENT='订单详情列表';

-- ----------------------------
-- Records of lkt_order_details
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_payment
-- ----------------------------
DROP TABLE IF EXISTS `lkt_payment`;
CREATE TABLE `lkt_payment` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '支付名称',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1:线上、2:线下',
  `class_name` varchar(50) NOT NULL COMMENT '支付类名称',
  `description` text COMMENT '描述',
  `logo` varchar(255) NOT NULL COMMENT '支付方式logo图片路径',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 1启用 0禁用',
  `sort` smallint(5) NOT NULL DEFAULT '99' COMMENT '排序',
  `note` text COMMENT '支付说明',
  `poundage` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `poundage_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '手续费方式 1百分比 2固定值',
  `client_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1:PC端 2:移动端 3:通用',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COMMENT='支付方式表';

