  `express_num` varchar(255) NOT NULL COMMENT '快递单号',
  `uid` varchar(32) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `oid` varchar(32) NOT NULL DEFAULT '0' COMMENT '订单id',
  `add_data` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '填写时间',
