  `appsecret` varchar(100) DEFAULT NULL COMMENT '第三方平台秘钥',
  `check_token` varchar(255) DEFAULT NULL COMMENT '消息检验Token，第三方平台设置',
  `encrypt_key` varchar(255) DEFAULT NULL COMMENT '消息加减密key',
  `serve_domain` text COMMENT '服务器域名',
  `work_domain` text COMMENT '业务域名',
  `redirect_url` text COMMENT '授权回调地址',
  `mini_url` text COMMENT '小程序接口地址',
  `kefu_url` text COMMENT '客服接口url',
  `qr_code` text COMMENT '体验二维码url',
  `H5` text COMMENT 'H5页面地址',
  `endurl` text COMMENT '根目录路径',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='第三方授权表';

-- ----------------------------
-- Records of lkt_third
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_third_mini_info
-- ----------------------------
DROP TABLE IF EXISTS `lkt_third_mini_info`;
CREATE TABLE `lkt_third_mini_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `nick_name` varchar(100) DEFAULT NULL COMMENT '授权方昵称',
  `authorizer_appid` varchar(100) DEFAULT NULL COMMENT '授权小程序appid',
  `authorizer_access_token` varchar(255) DEFAULT NULL COMMENT '授权方接口调用凭据（在授权的公众号或小程序具备API权限时，才有此返回值），也简称为令牌',
  `authorizer_expires` int(11) unsigned DEFAULT NULL COMMENT '有效期（在授权的公众号或小程序具备API权限时，才有此返回值）',
  `authorizer_refresh_token` varchar(255) DEFAULT NULL COMMENT '接口调用凭据刷新令牌',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `func_info` longtext COMMENT '授权给开发者的权限集列表',
  `expires_time` int(11) DEFAULT NULL COMMENT '过期时间戳',
  `company_id` varchar(100) DEFAULT NULL COMMENT '公司id',
  `head_img` varchar(255) DEFAULT NULL COMMENT '授权方头像',
  `verify_type_info` varchar(250) DEFAULT NULL COMMENT '授权方认证类型，-1代表未认证，0代表微信认证',
  `user_name` varchar(255) DEFAULT NULL COMMENT '小程序的原始ID',
  `signature` varchar(255) DEFAULT NULL COMMENT '帐号介绍',
  `principal_name` varchar(255) DEFAULT NULL COMMENT '小程序的主体名称',
  `business_info` varchar(255) DEFAULT NULL COMMENT '开通状况（0代表未开通，1代表已开通）',
  `qrcode_url` varchar(255) DEFAULT NULL COMMENT '二维码图片的URL，开发者最好自行也进行保存',
  `miniprograminfo` longtext COMMENT '根据这个字段判断是否为小程序类型授权',
  `store_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '商城id',
  `auditid` varchar(100) DEFAULT NULL COMMENT '审核编号',
  `review_mark` tinyint(2) DEFAULT '1' COMMENT '审核状态 1：未审核 2：审核中 3：审核失败 4：审核成功',
  `issue_mark` tinyint(2) DEFAULT '1' COMMENT '发布状态 1：未发布  2：发布失败 3：发布成功',
  `submit_time` datetime DEFAULT NULL COMMENT '审核提价时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COMMENT='授权小程序信息表';

-- ----------------------------
-- Records of lkt_third_mini_info
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_third_template
-- ----------------------------
DROP TABLE IF EXISTS `lkt_third_template`;
CREATE TABLE `lkt_third_template` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `template_id` varchar(50) DEFAULT NULL COMMENT '微信端模板id',
  `wx_desc` varchar(100) DEFAULT NULL COMMENT 'wx模板描述',
  `wx_version` varchar(100) DEFAULT NULL COMMENT 'wx模板版本号',
  `wx_create_time` int(11) DEFAULT NULL COMMENT '添加进开放平台模板库时间戳',
  `lk_version` varchar(255) DEFAULT NULL COMMENT '后台定义的模板编号',
  `lk_desc` text COMMENT '后台模板描述',
  `img_url` varchar(150) DEFAULT NULL COMMENT '模板图片路劲',
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `trade_data` varchar(50) DEFAULT NULL COMMENT '数据字典-行业',
  `is_use` tinyint(2) DEFAULT '1' COMMENT '是否应用 0：不应用 1：应用',
  `update_time` datetime DEFAULT NULL COMMENT '模板更新时间',
  `title` varchar(255) DEFAULT NULL COMMENT '模板名称',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 COMMENT='小程序模板表';

-- ----------------------------
-- Records of lkt_third_template
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_ui_navigation_bar
-- ----------------------------
DROP TABLE IF EXISTS `lkt_ui_navigation_bar`;
CREATE TABLE `lkt_ui_navigation_bar` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `name` varchar(255) NOT NULL COMMENT '数据名称',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT '图片',
  `type` tinyint(4) DEFAULT '0' COMMENT '跳转类型 1.分类 2.商品 3.店铺',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT '路径',
  `sort` int(11) DEFAULT '100' COMMENT '排序',
  `add_date` datetime DEFAULT '0000-00-00 00:00:00' COMMENT '添加时间',
  `isshow` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否显示',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8 COMMENT='UI导航栏表';

-- ----------------------------
-- Records of lkt_ui_navigation_bar
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_upload_set
-- ----------------------------
DROP TABLE IF EXISTS `lkt_upload_set`;
CREATE TABLE `lkt_upload_set` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `upserver` tinyint(4) NOT NULL DEFAULT '2' COMMENT '上传服务器:1,本地　2,阿里云 3,腾讯云 4,七牛云',
  `type` char(30) DEFAULT NULL COMMENT '类别',
  `attr` char(100) NOT NULL COMMENT '属性',
  `attrvalue` varchar(100) NOT NULL DEFAULT '' COMMENT '值',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1116 DEFAULT CHARSET=utf8 COMMENT='上传配置表';

-- ----------------------------
-- Records of lkt_upload_set
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_user
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user`;
CREATE TABLE `lkt_user` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) DEFAULT NULL COMMENT '用户id',
  `user_name` varchar(150) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '用户昵称',
  `access_id` varchar(255) DEFAULT NULL COMMENT '授权id',
  `access_key` varchar(32) DEFAULT NULL COMMENT '授权密钥',
  `wx_id` varchar(50) DEFAULT NULL COMMENT '微信id',
  `wx_name` varbinary(150) DEFAULT NULL COMMENT '微信昵称',
  `gzh_id` varchar(50) DEFAULT '' COMMENT '公众号id',
  `zfb_id` varchar(50) DEFAULT NULL COMMENT '支付宝id',
  `bd_id` varchar(50) DEFAULT NULL COMMENT '百度id',
  `tt_id` varchar(50) DEFAULT NULL COMMENT '头条id',
  `clientid` varchar(255) DEFAULT NULL COMMENT '推送客户端ID',
  `sex` int(11) DEFAULT NULL COMMENT '性别 0:未知 1:男 2:女',
  `headimgurl` mediumtext COMMENT '微信头像',
  `province` varchar(50) DEFAULT '' COMMENT '省',
  `city` varchar(50) DEFAULT '' COMMENT '市',
  `county` varchar(50) DEFAULT '' COMMENT '县',
  `detailed_address` varchar(100) DEFAULT NULL COMMENT '详细地址',
  `money` decimal(12,2) DEFAULT '0.00' COMMENT '金额',
  `score` int(11) unsigned DEFAULT '0' COMMENT '积分',
  `lock_score` int(11) unsigned DEFAULT '0' COMMENT '冻结的积分',
  `password` char(32) DEFAULT NULL COMMENT '支付密码',
  `Register_data` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `e_mail` varchar(30) DEFAULT NULL COMMENT '邮箱',
  `real_name` varchar(100) DEFAULT NULL COMMENT '真实姓名',
  `mobile` varchar(20) DEFAULT NULL COMMENT '手机',
  `birthday` timestamp NULL DEFAULT NULL COMMENT '出生日期',
  `wechat_id` varchar(50) DEFAULT '' COMMENT '微信号',
  `address` varchar(300) DEFAULT NULL COMMENT '地址',
  `Bank_name` varchar(30) DEFAULT NULL COMMENT '银行名称',
  `Cardholder` varchar(30) DEFAULT NULL COMMENT '持卡人',
  `Bank_card_number` varchar(30) DEFAULT NULL COMMENT '银行卡号',
  `share_num` int(11) DEFAULT '0' COMMENT '分享次数',
  `Referee` char(15) DEFAULT NULL COMMENT '推荐人',
  `access_token` varchar(32) DEFAULT '' COMMENT '访问令牌',
  `consumer_money` decimal(12,2) DEFAULT '0.00' COMMENT '消费金',
  `img_token` varchar(32) DEFAULT NULL COMMENT '分享图片id',
  `zhanghao` varchar(32) DEFAULT NULL COMMENT '账号',
  `mima` varchar(32) DEFAULT NULL COMMENT '密码',
  `source` tinyint(4) NOT NULL DEFAULT '1' COMMENT '来源 1.小程序 2.app 3.支付宝小程序 4.头条小程序 5.百度小程序 6.pc端 7.H5',
  `login_num` int(11) DEFAULT '0' COMMENT '登录次数',
  `verification_time` timestamp NULL DEFAULT NULL COMMENT '验证支付密码时间',
  `parameter` text COMMENT '参数',
  `is_lock` tinyint(2) DEFAULT '0' COMMENT '是否冻结 0-不冻结 1-冻结',
  `last_time` timestamp NULL DEFAULT NULL COMMENT '最后一次登录时间',
  `grade` int(11) DEFAULT '0' COMMENT '会员级别 0--普通会员 ',
  `tui_id` char(50) DEFAULT NULL COMMENT '会员推荐人id',
  `grade_add` timestamp NULL DEFAULT NULL COMMENT '充值会员等级时间',
  `grade_m` tinyint(4) DEFAULT NULL COMMENT '开通方式 1-包月 2-包季 3-包年',
  `grade_end` timestamp NULL DEFAULT NULL COMMENT '会员等级到期时间',
  `is_out` tinyint(2) DEFAULT '0' COMMENT '是否到期 0-未到期  1-已到期',
  `is_box` tinyint(2) DEFAULT '1' COMMENT '是否同意续费弹框 0-不同意 1 同意',
  `mch_token` text COMMENT '店铺token',
  `lang` varchar(255) DEFAULT 'zh-cn' COMMENT '语言',
  PRIMARY KEY (`id`),
  KEY `index_user_id` (`user_id`),
  KEY `index_store_id` (`store_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1404 DEFAULT CHARSET=utf8 COMMENT='会员列表';

-- ----------------------------
-- Records of lkt_user
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_user_address
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_address`;
CREATE TABLE `lkt_user_address` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '地址id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `name` varchar(10) NOT NULL COMMENT '收货人',
  `tel` char(15) NOT NULL COMMENT '联系方式',
  `sheng` varchar(200) NOT NULL DEFAULT '0' COMMENT '省id',
  `city` varchar(200) NOT NULL DEFAULT '0' COMMENT '市id',
  `quyu` varchar(200) NOT NULL DEFAULT '0' COMMENT '区域id',
  `address` varchar(200) NOT NULL COMMENT '收货地址（不加省市区）',
  `address_xq` varchar(255) NOT NULL COMMENT '省市区+详细地址',
  `code` int(11) NOT NULL DEFAULT '0' COMMENT '邮政编号',
  `uid` varchar(32) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `is_default` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否默认地址 1默认',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=661 DEFAULT CHARSET=utf8 COMMENT='用户收货地址表';

-- ----------------------------
-- Records of lkt_user_address
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_user_bank_card
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_bank_card`;
CREATE TABLE `lkt_user_bank_card` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(15) NOT NULL COMMENT '用户ID',
  `Cardholder` varchar(30) DEFAULT NULL COMMENT '持卡人',
  `id_card` varchar(30) DEFAULT NULL COMMENT '身份证',
  `Bank_name` varchar(30) DEFAULT NULL COMMENT '银行名称',
  `branch` varchar(250) DEFAULT NULL COMMENT '支行名称',
  `Bank_card_number` varchar(30) DEFAULT NULL COMMENT '银行卡号',
  `mobile` varchar(20) DEFAULT NULL COMMENT '手机',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `is_default` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否默认地址 1默认',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8 COMMENT='用户退货表';

-- ----------------------------
-- Records of lkt_user_bank_card
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_user_collection
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_collection`;
CREATE TABLE `lkt_user_collection` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(32) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `p_id` int(11) DEFAULT NULL COMMENT '产品id',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `type` int(11) DEFAULT '1' COMMENT '收藏类型 1.普通收藏 2.积分商城收藏',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=622 DEFAULT CHARSET=utf8 COMMENT='收藏表';

-- ----------------------------
-- Records of lkt_user_collection
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_user_distribution
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_distribution`;
CREATE TABLE `lkt_user_distribution` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(32) NOT NULL COMMENT '用户ID',
  `pid` varchar(32) NOT NULL COMMENT '上级id',
  `level` int(11) NOT NULL COMMENT '等级',
  `lt` int(11) NOT NULL COMMENT 'lt',
  `rt` int(11) NOT NULL COMMENT 'rt',
  `uplevel` int(11) NOT NULL COMMENT '第几代',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `usets` varchar(255) DEFAULT NULL,
  `commission` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '个人佣金',
  `onlyamount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '累计消费',
  `allamount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '销售业绩',
  `one_put` decimal(11,2) NOT NULL DEFAULT '0.00' COMMENT '个人进货奖励已经发放最大条件',
  `team_put` decimal(11,2) NOT NULL DEFAULT '0.00' COMMENT '团队业绩奖励已经发放最大',
  `accumulative` decimal(12,2) DEFAULT '0.00' COMMENT '累计佣金',
  `tx_commission` decimal(12,2) DEFAULT '0.00' COMMENT '可提现佣金',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 COMMENT='分销关联表';

-- ----------------------------
-- Records of lkt_user_distribution
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for lkt_user_first
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_first`;
CREATE TABLE `lkt_user_first` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` char(50) DEFAULT NULL COMMENT '用户id',
  `grade_id` int(11) DEFAULT NULL COMMENT '会员等级id',
  `level` int(11) DEFAULT NULL COMMENT '首次开通会员级别',
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `is_use` tinyint(2) DEFAULT '0' COMMENT '是否使用了首次开通赠送商品券 0-未使用 1-已使用',
  `sNo` char(50) DEFAULT NULL COMMENT '订单编号',
  `end_time` datetime DEFAULT NULL COMMENT '兑换券失效时间',
  `attr_id` int(11) DEFAULT NULL COMMENT '兑换商品的规格id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=146 DEFAULT CHARSET=utf8 COMMENT='等级会员首次开通表';

-- ----------------------------
-- Records of lkt_user_first
-- ----------------------------
BEGIN;
COMMIT;

