DROP PROCEDURE IF EXISTS `mysqlInnerDb`;
delimiter ;;
CREATE PROCEDURE `mysqlInnerDb`()
begin 
	declare i int default 0;
set i = (select count(1) from lkt_sku );
select i;
end
;;
delimiter ;

